    GLFWwindow* window_=nullptr;fs::path root_,current_,state_path_;std::vector<fs::path> files_;std::vector<Node> nodes_;AssetStore assets_;CocosCsdEngine engine_;
    int selected_=-1;bool dirty_=false,fit_pending_=true,dock_built_=false,dragging_=false,drag_history_pushed_=false;float zoom_=1;ImVec2 origin_{},drag_mouse_{};Vec2 scene_{1280,720},drag_position_{};ImGuiID dock_id_=0;
