bool CsdEditor::init(){if(!glfwInit())return false;glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR,3);glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR,2);glfwWindowHint(GLFW_OPENGL_PROFILE,GLFW_OPENGL_CORE_PROFILE);window_=glfwCreateWindow(1600,900,"Cocos Studio CSD UI Editor",nullptr,nullptr);if(!window_)return false;glfwMakeContextCurrent(window_);glfwSwapInterval(1);IMGUI_CHECKVERSION();ImGui::CreateContext();ImGuiIO& io=ImGui::GetIO();io.ConfigFlags|=ImGuiConfigFlags_NavEnableKeyboard|ImGuiConfigFlags_DockingEnable;ImGui::StyleColorsDark();ImGuiStyle& style=ImGui::GetStyle();style.ScaleAllSizes(0.85f);style.WindowPadding={8,8};style.FramePadding={5,4};style.ItemSpacing={8,6};style.ItemInnerSpacing={6,4};style.IndentSpacing=14;ImGui_ImplGlfw_InitForOpenGL(window_,true);ImGui_ImplOpenGL3_Init("#version 150");state_path_=fs::current_path()/"csd_editor_state.json";load_state();scan();if(!current_.empty()&&fs::exists(current_))load(current_);else if(!files_.empty())load(files_.front());return true;}
void CsdEditor::shutdown(){save_state();assets_.clear();ImGui_ImplOpenGL3_Shutdown();ImGui_ImplGlfw_Shutdown();ImGui::DestroyContext();if(window_)glfwDestroyWindow(window_);glfwTerminate();}
void CsdEditor::run(){while(!glfwWindowShouldClose(window_)){glfwPollEvents();ImGui_ImplOpenGL3_NewFrame();ImGui_ImplGlfw_NewFrame();ImGui::NewFrame();shortcuts();menu();dockspace();build_dock();files_panel();hierarchy_panel();properties_panel();canvas_panel();ImGui::Render();int w,h;glfwGetFramebufferSize(window_,&w,&h);glViewport(0,0,w,h);glClearColor(.08f,.09f,.11f,1);glClear(GL_COLOR_BUFFER_BIT);ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());glfwSwapBuffers(window_);}}

void CsdEditor::scan(){files_.clear();std::error_code ec;if(root_.empty()){status_="Set a UI root folder to begin.";copy_buf(root_buf_,"");return;}if(!fs::exists(root_,ec)){status_=std::string(engine_.name())+" root does not exist: "+root_.string();copy_buf(root_buf_,root_.string().c_str());return;}copy_buf(root_buf_,root_.string().c_str());for(auto it=fs::recursive_directory_iterator(root_,fs::directory_options::skip_permission_denied,ec);it!=fs::recursive_directory_iterator();it.increment(ec)){if(ec){ec.clear();continue;}if(it->is_regular_file()&&lower(it->path().extension().string())==engine_.file_extension())files_.push_back(it->path());}std::sort(files_.begin(),files_.end());status_="Found "+std::to_string(files_.size())+" "+engine_.file_extension()+" files";}
bool CsdEditor::load(const fs::path& p){selected_=-1;dirty_=false;LoadResult r=engine_.load(p,nodes_,assets_);status_=r.status;if(!r.ok)return false;current_=p;scene_=r.scene;selected_=nodes_.empty()?-1:0;sync_fields();fit_pending_=true;save_state();return true;}
void CsdEditor::sync_fields(){if(selected_<0||selected_>=(int)nodes_.size())return;Node& n=nodes_[selected_];NodeProperties p=engine_.read_properties(n);copy_buf(name_buf_,p.name.c_str());pos_[0]=p.position.x;pos_[1]=p.position.y;size_[0]=p.size.x;size_[1]=p.size.y;scale_[0]=p.scale.x;scale_[1]=p.scale.y;anchor_[0]=p.anchor.x;anchor_[1]=p.anchor.y;rotation_=p.rotation;visible_=p.visible;touch_=p.touch;copy_buf(text_buf_,p.text.c_str());font_size_=(int)attrf(n.xml,"FontSize",20);clip_=attrb(n.xml,"ClipAble",false);scale9_=attrb(n.xml,"Scale9Enable",false);outline_=attrb(n.xml,"OutlineEnabled",false);shadow_=attrf(n.xml,"ShadowOffsetX",0)!=0||attrf(n.xml,"ShadowOffsetY",0)!=0;bounce_=attrb(n.xml,"IsBounceEnabled",false);back_alpha_=(int)attrf(n.xml,"BackColorAlpha",102);edge_[0]=(int)attrf(n.xml,"LeftEage",0);edge_[1]=(int)attrf(n.xml,"RightEage",0);edge_[2]=(int)attrf(n.xml,"TopEage",0);edge_[3]=(int)attrf(n.xml,"BottomEage",0);XMLElement* c=child(n.xml,"CColor");color_[0]=attrf(c,"R",255)/255.f;color_[1]=attrf(c,"G",255)/255.f;color_[2]=attrf(c,"B",255)/255.f;color_[3]=attrf(c,"A",255)/255.f;if(!c&&child(n.xml,"SingleColor")){c=child(n.xml,"SingleColor");color_[0]=attrf(c,"R",150)/255.f;color_[1]=attrf(c,"G",200)/255.f;color_[2]=attrf(c,"B",255)/255.f;color_[3]=attrf(c,"A",255)/255.f;}XMLElement* f=child(n.xml,"FileData");if(!f)f=child(n.xml,"NormalFileData");copy_buf(path_buf_,attrs(f,"Path"));copy_buf(plist_buf_,attrs(f,"Plist"));copy_buf(type_buf_,attrs(f,"Type"));f=child(n.xml,"NormalFileData");copy_buf(normal_path_buf_,attrs(f,"Path"));copy_buf(normal_plist_buf_,attrs(f,"Plist"));f=child(n.xml,"PressedFileData");copy_buf(pressed_path_buf_,attrs(f,"Path"));copy_buf(pressed_plist_buf_,attrs(f,"Plist"));f=child(n.xml,"DisabledFileData");copy_buf(disabled_path_buf_,attrs(f,"Path"));copy_buf(disabled_plist_buf_,attrs(f,"Plist"));}
void CsdEditor::apply_fields(){if(selected_<0)return;if(dragging_&&!drag_history_pushed_){push_undo();drag_history_pushed_=true;}else if(!dragging_)push_undo();NodeProperties p;p.name=name_buf_.data();p.visible=visible_;p.touch=touch_;p.position={pos_[0],pos_[1]};p.size={size_[0],size_[1]};p.scale={scale_[0],scale_[1]};p.anchor={anchor_[0],anchor_[1]};p.rotation=rotation_;engine_.write_common_properties(nodes_[selected_],p,assets_,nodes_);dirty_=true;status_="Modified "+current_.filename().string();}
void CsdEditor::save(){if(current_.empty())return;if(engine_.save(current_)){dirty_=false;status_="Saved "+current_.string();}else status_="Save failed: "+current_.string();}
void CsdEditor::save_state(){json j={{"root",root_.string()},{"current",current_.string()}};std::ofstream o(state_path_);if(o)o<<j.dump(2)<<'\n';}
void CsdEditor::load_state(){std::ifstream i(state_path_);if(!i){copy_buf(root_buf_,root_.string().c_str());return;}try{json j;i>>j;if(root_.empty()&&j.contains("root"))root_=j["root"].get<std::string>();if(j.contains("current"))current_=j["current"].get<std::string>();assets_.set_root(root_);copy_buf(root_buf_,root_.string().c_str());}catch(...){copy_buf(root_buf_,root_.string().c_str());} }

void CsdEditor::push_undo(){undo_.push_back(engine_.snapshot());if(undo_.size()>100)undo_.erase(undo_.begin());redo_.clear();}
bool CsdEditor::restore_xml(const std::string& xml){LoadResult r;if(!engine_.restore_snapshot(xml,current_.filename().string(),nodes_,assets_,&r))return false;scene_=r.scene;selected_=nodes_.empty()?-1:std::min(selected_,(int)nodes_.size()-1);sync_fields();dirty_=true;return true;}
void CsdEditor::undo(){if(undo_.empty())return;redo_.push_back(engine_.snapshot());std::string s=undo_.back();undo_.pop_back();restore_xml(s);status_="Undo";}
void CsdEditor::redo(){if(redo_.empty())return;undo_.push_back(engine_.snapshot());std::string s=redo_.back();redo_.pop_back();restore_xml(s);status_="Redo";}
void CsdEditor::shortcuts(){ImGuiIO& io=ImGui::GetIO();if(io.KeyCtrl&&ImGui::IsKeyPressed(ImGuiKey_S))save();if(io.KeyCtrl&&ImGui::IsKeyPressed(ImGuiKey_Z))undo();if(io.KeyCtrl&&ImGui::IsKeyPressed(ImGuiKey_Y))redo();if(ImGui::IsKeyPressed(ImGuiKey_F))fit_pending_=true;}
void CsdEditor::menu(){if(ImGui::BeginMainMenuBar()){if(ImGui::BeginMenu("File")){if(ImGui::MenuItem("Save","Ctrl+S",false,!current_.empty()))save();if(ImGui::MenuItem("Rescan"))scan();if(ImGui::MenuItem("Exit"))glfwSetWindowShouldClose(window_,1);ImGui::EndMenu();}if(ImGui::BeginMenu("View")){if(ImGui::MenuItem("Fit to window","F"))fit_pending_=true;if(ImGui::MenuItem("Actual size"))zoom_=1;ImGui::EndMenu();}ImGui::Separator();ImGui::TextUnformatted(dirty_?"* Unsaved":"Saved");ImGui::Separator();ImGui::TextUnformatted(status_.c_str());ImGui::EndMainMenuBar();}}
void CsdEditor::dockspace(){ImGuiViewport* vp=ImGui::GetMainViewport();ImGui::SetNextWindowPos(vp->WorkPos);ImGui::SetNextWindowSize(vp->WorkSize);ImGui::SetNextWindowViewport(vp->ID);ImGuiWindowFlags f=ImGuiWindowFlags_NoDocking|ImGuiWindowFlags_NoTitleBar|ImGuiWindowFlags_NoCollapse|ImGuiWindowFlags_NoResize|ImGuiWindowFlags_NoMove|ImGuiWindowFlags_NoBringToFrontOnFocus|ImGuiWindowFlags_NoNavFocus|ImGuiWindowFlags_NoBackground;ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding,{0,0});ImGui::Begin("DockHost",nullptr,f);ImGui::PopStyleVar();dock_id_=ImGui::GetID("CsdDock");ImGui::DockSpace(dock_id_,{0,0},ImGuiDockNodeFlags_PassthruCentralNode);ImGui::End();}
void CsdEditor::build_dock(){if(dock_built_||!dock_id_)return;dock_built_=true;ImGuiViewport* vp=ImGui::GetMainViewport();ImGui::DockBuilderRemoveNode(dock_id_);ImGui::DockBuilderAddNode(dock_id_,ImGuiDockNodeFlags_DockSpace);ImGui::DockBuilderSetNodeSize(dock_id_,vp->WorkSize);ImGuiID center=dock_id_,left=ImGui::DockBuilderSplitNode(center,ImGuiDir_Left,.22f,nullptr,&center),right=ImGui::DockBuilderSplitNode(center,ImGuiDir_Right,.26f,nullptr,&center),hier=ImGui::DockBuilderSplitNode(left,ImGuiDir_Down,.48f,nullptr,&left);ImGui::DockBuilderDockWindow("CSD Files",left);ImGui::DockBuilderDockWindow("Hierarchy",hier);ImGui::DockBuilderDockWindow("Properties",right);ImGui::DockBuilderDockWindow("Canvas",center);ImGui::DockBuilderFinish(dock_id_);}
void CsdEditor::files_panel(){ImGui::Begin("CSD Files");ImGui::Text("%d files",(int)files_.size());ImGui::SetNextItemWidth(-70);ImGui::InputTextWithHint("##filter","Search file or folder...",filter_buf_.data(),filter_buf_.size());ImGui::SameLine();if(ImGui::Button("Clear"))filter_buf_[0]='\0';if(ImGui::CollapsingHeader("CSD Root")){ImGui::InputText("##root",root_buf_.data(),root_buf_.size());if(ImGui::Button("Apply root")){root_=fs::path(root_buf_.data());assets_.set_root(root_);scan();}}std::string q=lower(filter_buf_.data());int shown=0;for(const auto& p:files_){std::string rel=slash(p.lexically_relative(root_));if(q.empty()||lower(rel).find(q)!=std::string::npos)++shown;}ImGui::Text("Matches: %d",shown);ImGui::BeginChild("filelist");for(const auto& p:files_){std::string rel=slash(p.lexically_relative(root_));if(!q.empty()&&lower(rel).find(q)==std::string::npos)continue;bool sel=p==current_;if(ImGui::Selectable(rel.c_str(),sel))load(p);if(sel)ImGui::SetItemDefaultFocus();}ImGui::EndChild();ImGui::End();}
void CsdEditor::tree_node(int index){Node& n=nodes_[index];ImGuiTreeNodeFlags f=ImGuiTreeNodeFlags_OpenOnArrow|ImGuiTreeNodeFlags_SpanAvailWidth;if(n.children.empty())f|=ImGuiTreeNodeFlags_Leaf;if(index==selected_)f|=ImGuiTreeNodeFlags_Selected;std::string label=n.name+"  ["+n.type+"]##"+std::to_string(index);bool open=ImGui::TreeNodeEx(label.c_str(),f);if(ImGui::IsItemClicked()){selected_=index;sync_fields();}if(open){for(int c:n.children)tree_node(c);ImGui::TreePop();}}
void CsdEditor::hierarchy_panel(){ImGui::Begin("Hierarchy");if(!nodes_.empty())tree_node(0);ImGui::End();}
void CsdEditor::properties_panel(){ImGui::Begin("Properties");if(selected_<0){ImGui::TextUnformatted("No node selected");ImGui::End();return;}Node& n=nodes_[selected_];auto set_tex=[&](const char* tag,std::array<char,256>& path,std::array<char,256>& plist){XMLElement* f=child(n.xml,tag);if(!f&&!path[0]&&!plist[0])return;if(!f)f=ensure_child(engine_.document(),n.xml,tag);f->SetAttribute("Path",path.data());if(plist[0])f->SetAttribute("Plist",plist.data());else f->DeleteAttribute("Plist");if(!f->Attribute("Type"))f->SetAttribute("Type",plist[0]?"PlistSubImage":"Normal");};auto finish=[&](){engine_.refresh_node(n,assets_);if(!nodes_.empty())engine_.layout(nodes_,0,{});dirty_=true;status_="Modified "+current_.filename().string();};std::string t=lower(n.type);ImGui::TextWrapped("%s",n.type.c_str());ImGui::Separator();bool changed=false;changed|=ImGui::InputText("Name",name_buf_.data(),name_buf_.size());changed|=ImGui::Checkbox("Visible",&visible_);changed|=ImGui::Checkbox("Touch",&touch_);changed|=ImGui::DragFloat2("Position",pos_,1);changed|=ImGui::DragFloat2("Size",size_,1,0);changed|=ImGui::DragFloat2("Scale",scale_,.01f);changed|=ImGui::DragFloat("Rotation",&rotation_,.2f);changed|=ImGui::DragFloat2("Anchor",anchor_,.01f,0,1);if(changed)apply_fields();ImGui::Separator();bool special=false;if(t.find("text")!=std::string::npos||t.find("label")!=std::string::npos){ImGui::TextUnformatted("Text");special|=ImGui::InputTextMultiline("Label",text_buf_.data(),text_buf_.size(),{0,48});special|=ImGui::DragInt("Font Size",&font_size_,1,1,200);special|=ImGui::ColorEdit4("Color",color_);special|=ImGui::Checkbox("Outline",&outline_);special|=ImGui::Checkbox("Shadow",&shadow_);if(special){push_undo();n.xml->SetAttribute("LabelText",text_buf_.data());n.xml->SetAttribute("FontSize",font_size_);n.xml->SetAttribute("OutlineEnabled",outline_?"True":"False");if(shadow_){n.xml->SetAttribute("ShadowOffsetX",2);n.xml->SetAttribute("ShadowOffsetY",-2);}else{n.xml->DeleteAttribute("ShadowOffsetX");n.xml->DeleteAttribute("ShadowOffsetY");}XMLElement* c=ensure_child(engine_.document(),n.xml,"CColor");c->SetAttribute("R",(int)(color_[0]*255));c->SetAttribute("G",(int)(color_[1]*255));c->SetAttribute("B",(int)(color_[2]*255));c->SetAttribute("A",(int)(color_[3]*255));finish();}}else if(t.find("button")!=std::string::npos){ImGui::TextUnformatted("Button");special|=ImGui::InputText("Button Text",text_buf_.data(),text_buf_.size());special|=ImGui::DragInt("Font Size",&font_size_,1,1,200);special|=ImGui::InputText("Normal Path",normal_path_buf_.data(),normal_path_buf_.size());special|=ImGui::InputText("Normal Plist",normal_plist_buf_.data(),normal_plist_buf_.size());special|=ImGui::InputText("Pressed Path",pressed_path_buf_.data(),pressed_path_buf_.size());special|=ImGui::InputText("Pressed Plist",pressed_plist_buf_.data(),pressed_plist_buf_.size());special|=ImGui::InputText("Disabled Path",disabled_path_buf_.data(),disabled_path_buf_.size());special|=ImGui::InputText("Disabled Plist",disabled_plist_buf_.data(),disabled_plist_buf_.size());special|=ImGui::Checkbox("Scale9",&scale9_);special|=ImGui::DragInt4("Insets L/R/T/B",edge_,1,0,999);if(special){push_undo();n.xml->SetAttribute("ButtonText",text_buf_.data());n.xml->SetAttribute("FontSize",font_size_);n.xml->SetAttribute("Scale9Enable",scale9_?"True":"False");n.xml->SetAttribute("LeftEage",edge_[0]);n.xml->SetAttribute("RightEage",edge_[1]);n.xml->SetAttribute("TopEage",edge_[2]);n.xml->SetAttribute("BottomEage",edge_[3]);set_tex("NormalFileData",normal_path_buf_,normal_plist_buf_);set_tex("PressedFileData",pressed_path_buf_,pressed_plist_buf_);set_tex("DisabledFileData",disabled_path_buf_,disabled_plist_buf_);finish();}}else if(t.find("image")!=std::string::npos||t.find("sprite")!=std::string::npos){ImGui::TextUnformatted("Texture");special|=ImGui::InputText("Path",path_buf_.data(),path_buf_.size());special|=ImGui::InputText("Plist",plist_buf_.data(),plist_buf_.size());special|=ImGui::InputText("Type",type_buf_.data(),type_buf_.size());special|=ImGui::Checkbox("Scale9",&scale9_);special|=ImGui::DragInt4("Insets L/R/T/B",edge_,1,0,999);if(special){push_undo();XMLElement* f=ensure_child(engine_.document(),n.xml,"FileData");f->SetAttribute("Path",path_buf_.data());if(plist_buf_[0])f->SetAttribute("Plist",plist_buf_.data());else f->DeleteAttribute("Plist");f->SetAttribute("Type",type_buf_[0]?type_buf_.data():(plist_buf_[0]?"PlistSubImage":"Normal"));n.xml->SetAttribute("Scale9Enable",scale9_?"True":"False");n.xml->SetAttribute("LeftEage",edge_[0]);n.xml->SetAttribute("RightEage",edge_[1]);n.xml->SetAttribute("TopEage",edge_[2]);n.xml->SetAttribute("BottomEage",edge_[3]);finish();}}else if(t.find("panel")!=std::string::npos||t.find("scroll")!=std::string::npos||t.find("list")!=std::string::npos||t.find("page")!=std::string::npos){ImGui::TextUnformatted("Container");special|=ImGui::Checkbox("Clip",&clip_);special|=ImGui::Checkbox("Bounce",&bounce_);special|=ImGui::DragInt("Back Alpha",&back_alpha_,1,0,255);special|=ImGui::ColorEdit4("Back Color",color_);if(special){push_undo();n.xml->SetAttribute("ClipAble",clip_?"True":"False");n.xml->SetAttribute("IsBounceEnabled",bounce_?"True":"False");n.xml->SetAttribute("BackColorAlpha",back_alpha_);XMLElement* c=ensure_child(engine_.document(),n.xml,"SingleColor");c->SetAttribute("R",(int)(color_[0]*255));c->SetAttribute("G",(int)(color_[1]*255));c->SetAttribute("B",(int)(color_[2]*255));c->SetAttribute("A",(int)(color_[3]*255));finish();}}else{ImGui::TextWrapped("Text: %s",n.text.c_str());XMLElement* f=child(n.xml,"FileData");if(!f)f=child(n.xml,"NormalFileData");if(f)ImGui::TextWrapped("Texture: %s",attrs(f,"Path"));}ImGui::Separator();ImGui::Text("Children: %d",(int)n.children.size());ImGui::End();}

ImVec2 CsdEditor::world_to_screen(Vec2 p)const{return{origin_.x+p.x*zoom_,origin_.y+(scene_.y-p.y)*zoom_};}
Vec2 CsdEditor::screen_to_world(ImVec2 p)const{return{(p.x-origin_.x)/zoom_,scene_.y-(p.y-origin_.y)/zoom_};}
void CsdEditor::draw_node(ImDrawList* dl,Node& n){if(!n.visible)return;ImVec2 p[4];for(int i=0;i<4;++i)p[i]=world_to_screen(n.corners[i]);if(n.region.valid()){ImVec2 uv[4]={{n.region.u0,n.region.v1},{n.region.u1,n.region.v1},{n.region.u1,n.region.v0},{n.region.u0,n.region.v0}};if(n.region.rotated){uv[0]={n.region.u1,n.region.v1};uv[1]={n.region.u1,n.region.v0};uv[2]={n.region.u0,n.region.v0};uv[3]={n.region.u0,n.region.v1};}dl->AddImageQuad((ImTextureID)n.region.texture->id,p[0],p[1],p[2],p[3],uv[0],uv[1],uv[2],uv[3],n.color);}else if(n.type.find("Panel")!=std::string::npos){XMLElement* c=child(n.xml,"SingleColor");ImU32 col=IM_COL32((int)attrf(c,"R",80),(int)attrf(c,"G",80),(int)attrf(c,"B",80),(int)attrf(n.xml,"BackColorAlpha",50));dl->AddQuadFilled(p[0],p[1],p[2],p[3],col);}if(!n.text.empty()){ImVec2 ts=ImGui::CalcTextSize(n.text.c_str());ImVec2 center={(p[0].x+p[2].x-ts.x)*.5f,(p[0].y+p[2].y-ts.y)*.5f};dl->AddText(center,n.color,n.text.c_str());}if(&n==&nodes_[selected_]){dl->AddQuad(p[0],p[1],p[2],p[3],IM_COL32(255,210,40,255),2);dl->AddText(p[3],IM_COL32(255,210,40,255),n.name.c_str());}}
int CsdEditor::hit_test(Vec2 w)const{for(int i=(int)nodes_.size()-1;i>=0;--i){const Node& n=nodes_[i];if(!n.visible)continue;float minx=n.corners[0].x,maxx=minx,miny=n.corners[0].y,maxy=miny;for(int k=1;k<4;++k){minx=std::min(minx,n.corners[k].x);maxx=std::max(maxx,n.corners[k].x);miny=std::min(miny,n.corners[k].y);maxy=std::max(maxy,n.corners[k].y);}if(w.x>=minx&&w.x<=maxx&&w.y>=miny&&w.y<=maxy)return i;}return-1;}
void CsdEditor::canvas_panel(){ImGui::Begin("Canvas");ImVec2 avail=ImGui::GetContentRegionAvail();if(fit_pending_&&scene_.x>0&&scene_.y>0){zoom_=std::clamp(std::min((avail.x-40)/scene_.x,(avail.y-40)/scene_.y),.03f,4.f);fit_pending_=false;}float w=scene_.x*zoom_,h=scene_.y*zoom_;ImVec2 pad={std::max(20.f,(avail.x-w)*.5f),std::max(20.f,(avail.y-h)*.5f)};ImGui::SetCursorPos({ImGui::GetCursorPosX()+pad.x,ImGui::GetCursorPosY()+pad.y});ImGui::InvisibleButton("canvas",{w,h},ImGuiButtonFlags_MouseButtonLeft);origin_=ImGui::GetItemRectMin();bool hovered=ImGui::IsItemHovered();ImDrawList* dl=ImGui::GetWindowDrawList();dl->AddRectFilled(origin_,{origin_.x+w,origin_.y+h},IM_COL32(35,37,42,255));for(Node& n:nodes_)draw_node(dl,n);ImGuiIO& io=ImGui::GetIO();if(hovered&&io.MouseWheel)zoom_=std::clamp(zoom_*(io.MouseWheel>0?1.12f:1/1.12f),.03f,8.f);if(hovered&&ImGui::IsMouseClicked(ImGuiMouseButton_Left)){int hit=hit_test(screen_to_world(io.MousePos));if(hit>=0){selected_=hit;sync_fields();dragging_=true;drag_history_pushed_=false;drag_mouse_=io.MousePos;drag_position_=nodes_[hit].position;}}if(dragging_&&ImGui::IsMouseDragging(ImGuiMouseButton_Left)&&selected_>=0){ImVec2 d={io.MousePos.x-drag_mouse_.x,io.MousePos.y-drag_mouse_.y};pos_[0]=drag_position_.x+d.x/zoom_;pos_[1]=drag_position_.y-d.y/zoom_;apply_fields();}if(ImGui::IsMouseReleased(ImGuiMouseButton_Left)){dragging_=false;drag_history_pushed_=false;}ImGui::End();}

int main(int argc,char** argv){fs::path root;bool validate=false;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--csd-root"&&i+1<argc)root=argv[++i];else if(a=="--validate-csd")validate=true;else if(a=="--help"||a=="-h"){std::printf("Usage: annotation_editor [--csd-root PATH] [--validate-csd]\n");return 0;}}if(validate){if(root.empty()){std::fprintf(stderr,"--validate-csd requires --csd-root PATH when no default root is configured.\n");return 1;}CocosCsdEngine engine;return engine.validate_root(root);}CsdEditor app(root);if(!app.init())return 1;app.run();app.shutdown();return 0;}
